import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const v=JSON.parse('{"title":"28 | 部门分类：如何表示设备类型与设备驱动？","description":"","frontmatter":{},"headers":[{"level":2,"title":"计算机的结构","slug":"计算机的结构","link":"#计算机的结构","children":[]},{"level":2,"title":"如何管理设备","slug":"如何管理设备","link":"#如何管理设备","children":[{"level":3,"title":"分权而治","slug":"分权而治","link":"#分权而治","children":[]},{"level":3,"title":"设备分类","slug":"设备分类","link":"#设备分类","children":[]}]},{"level":2,"title":"设备驱动","slug":"设备驱动","link":"#设备驱动","children":[{"level":3,"title":"设备","slug":"设备","link":"#设备","children":[]},{"level":3,"title":"驱动","slug":"驱动","link":"#驱动","children":[]},{"level":3,"title":"设备驱动的组织","slug":"设备驱动的组织","link":"#设备驱动的组织","children":[]},{"level":3,"title":"驱动程序功能","slug":"驱动程序功能","link":"#驱动程序功能","children":[]}]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"操作系统实战45讲/28-部门分类：如何表示设备类型与设备驱动？.md","filePath":"操作系统实战45讲/28-部门分类：如何表示设备类型与设备驱动？.md","lastUpdated":1779820584000}'),l={name:"操作系统实战45讲/28-部门分类：如何表示设备类型与设备驱动？.md"};function i(t,s,d,c,_,r){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_28-部门分类-如何表示设备类型与设备驱动" tabindex="-1">28 | 部门分类：如何表示设备类型与设备驱动？ <a class="header-anchor" href="#_28-部门分类-如何表示设备类型与设备驱动" aria-label="Permalink to &quot;28 | 部门分类：如何表示设备类型与设备驱动？&quot;">​</a></h1><p>你好，我是LMOS。</p><p>小到公司，大到国家，都有各种下属部门，比如我们国家现在有教育部、科学技术部、外交部，财政部等，这些部门各自负责完成不同的职能工作，如教育部负责教育事业和语言文字工作，科学技术部负责推动解决经济社会发展的重大科技问题。</p><p>既然大道相通，那我们的Cosmos中是否也是类似这样的结构呢？</p><p>答案是肯定的，在前面的课中，我们搞定了内存管理和进程管理，它们是内核不可分隔的，但是计算机中还有各种类型的设备需要管理。</p><p>我们的Cosmos也会“成立各类部门”，用于管理众多设备，一个部门负责一类设备。具体要怎么管理设备呢？你不妨带着这个问题，正式开始今天的学习！</p><p>这节课的代码，你可以从 <a href="https://gitee.com/lmos/cosmos/tree/master/lesson28~29/Cosmos" target="_blank" rel="noreferrer">这里</a> 下载。</p><h2 id="计算机的结构" tabindex="-1">计算机的结构 <a class="header-anchor" href="#计算机的结构" aria-label="Permalink to &quot;计算机的结构&quot;">​</a></h2><p>不知道你是否和我一样，经常把计算机的机箱打开，看看 CPU，看看内存条，看看显卡，看看主板上的各种芯片。</p><p>其实，这些芯片并非独立存在，而是以总线为基础连接在一起的，各自完成自己的工作，又能互相打配合，共同实现用户要求的功能。</p><p>为了帮你理清它们的连接关系，我为你画了一幅图，如下所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/394084/2f7697d94bee25d4c036eb4bca16ee4c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/394084/2f7697d94bee25d4c036eb4bca16ee4c.jpg" alt=""></a></p><p>上图是一个典型的桌面系统，你先不用管是物理上怎么样连接的，逻辑上就是这样的。实际可能比图中有更多或者更少的总线。但是总线有层级关系，各种设备通过总线相连。这里我们只需要记住，计算机中有很多种类的设备，脑中有刚才这幅图就行了。</p><h2 id="如何管理设备" tabindex="-1">如何管理设备 <a class="header-anchor" href="#如何管理设备" aria-label="Permalink to &quot;如何管理设备&quot;">​</a></h2><p>在前面的课程中，我们实现了管理内存和进程，其实进程从正面看它是管理应用程序的，反过来看它也是管理CPU的，它能使CPU的使用率达到最高。</p><p>管理内存和管理CPU是操作系统最核心的部分，但是这还不够，因为计算机不止有CPU，还有各种设备。</p><p>如果把计算机内部所有的设备和数据都描述成资源，操作系统内核无疑是这些资源的管理者。既然设备也是一种资源，如何高效管理它们，以便提供给应用进程使用和操作，就是操作系统内核的重要任务。</p><h3 id="分权而治" tabindex="-1">分权而治 <a class="header-anchor" href="#分权而治" aria-label="Permalink to &quot;分权而治&quot;">​</a></h3><p>一个国家之所以有那么多部门，就是要把管理工作分开，专权专职专责，对于操作系统也是一样。</p><p>现代计算机早已不限于只处理计算任务，它还可以呈现图像、音频，和远程计算机通信，储存大量数据，以及和用户交互。所以，计算机内部需要处理图像、音频、网络、储存、交互的设备。这从上面的图中也可以看得出来。</p><p>操作系统内核要控制这些设备，就要包含每个设备的控制代码。如果操作系统内核被设计为通用可移植的内核，那是相当可怕的。试想一下，这个世界上有如此多的设备，操作系统内核代码得多庞大，越庞大就越危险，因为其中一行代码有问题，整个操作系统就崩溃了。</p><p>可是仅仅只有这些问题吗？当然不是，我们还要考虑到后面这几点。</p><p>1.操作系统内核开发人员，不可能罗列世界上所有的设备，并为其写一套控制代码。</p><p>2.为了商业目的，有很多设备厂商并不愿意公开设备的编程细节。就算内核开发人员想为其写控制代码，实际也不可行。</p><p>3.如果设备更新换代，就要重写设备的控制代码，然后重新编译操作系统内核，这样的话操作很麻烦，操作系统内核开发人员和用户都可能受不了。</p><p>以上三点，足于证明这种方案根本不可取。</p><p>既然操作系统内核无法包含所有的设备控制代码，那就索性不包含，或者只包含最基本、最通用的设备控制代码。这样操作系统内核就可以非常通用，非常精巧。</p><p>但是要控制设备就必须要有设备的相关控制代码才行，所以我们要把设备控制代码独立出来，与操作系统内核分开、独立开发，设备控制代码可由设备厂商人员开发。</p><p>每个设备对应一个设备控制代码模块，操作系统内核要控制哪个设备，就加载相应的设备代码模块，以后不使用这个设备了，就可以删除对应的设备控制代码模块。</p><p>这种方式，给操作系统内核带来了 <strong>巨大的灵活性</strong>。设备厂商在发布新设备时，只要随之发布一个与此相关的设备控制代码模块就行了。</p><h3 id="设备分类" tabindex="-1">设备分类 <a class="header-anchor" href="#设备分类" aria-label="Permalink to &quot;设备分类&quot;">​</a></h3><p>要想管理设备，先要对其分门别类，在开始分类之前，你不妨先思考一个问题：操作系统内核所感知的设备，一定要与物理设备一一对应吗？</p><p>举个例子，储存设备，其实不管它是机械硬盘，还是TF卡，或者是一个设备控制代码模块，它向操作系统内核表明它是储存设备，但它完全有可能分配一块内存空间来储存数据，不必访问真正的储存设备。 <strong>所以，操作系统内核所感知的设备，并不需要和物理设备对应，这取决于设备控制代码自身的行为。</strong></p><p>操作系统内核所定义的设备，可称为内核设备或者逻辑设备，其实这只是对物理计算平台中几种类型设备的一种抽象。下面，我们在cosmos/include/knlinc/krldevice_t.h文件中对设备进行分类定义，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define NOT_DEVICE 0</span><span>               //不表示任何设备</span></span>
<span class="line"><span>#define BRIDGE_DEVICE 4</span><span>            //总线桥接器设备</span></span>
<span class="line"><span>#define CPUCORE_DEVICE 5</span><span>           //CPU设备，CPU也是设备</span></span>
<span class="line"><span>#define RAMCONTER_DEVICE 6</span><span>        //内存控制器设备</span></span>
<span class="line"><span>#define RAM_DEVICE 7</span><span>              //内存设备</span></span>
<span class="line"><span>#define USBHOSTCONTER_DEVICE 8</span><span>    //USB主控制设备</span></span>
<span class="line"><span>#define INTUPTCONTER_DEVICE 9</span><span>     //中断控制器设备</span></span>
<span class="line"><span>#define DMA_DEVICE 10</span><span>             //DMA设备</span></span>
<span class="line"><span>#define CLOCKPOWER_DEVICE 11</span><span>      //时钟电源设备</span></span>
<span class="line"><span>#define LCDCONTER_DEVICE 12</span><span>        //LCD控制器设备</span></span>
<span class="line"><span>#define NANDFLASH_DEVICE 13</span><span>       //nandflash设备</span></span>
<span class="line"><span>#define CAMERA_DEVICE 14</span><span>          //摄像头设备</span></span>
<span class="line"><span>#define UART_DEVICE 15</span><span>             //串口设备</span></span>
<span class="line"><span>#define TIMER_DEVICE 16</span><span>            //定时器设备</span></span>
<span class="line"><span>#define USB_DEVICE 17</span><span>              //USB设备</span></span>
<span class="line"><span>#define WATCHDOG_DEVICE 18</span><span>        //看门狗设备</span></span>
<span class="line"><span>#define RTC_DEVICE 22</span><span>              //实时时钟设备</span></span>
<span class="line"><span>#define SD_DEVICE 25</span><span>               //SD卡设备</span></span>
<span class="line"><span>#define AUDIO_DEVICE 26</span><span>            //音频设备</span></span>
<span class="line"><span>#define TOUCH_DEVICE 27</span><span>           //触控设备</span></span>
<span class="line"><span>#define NETWORK_DEVICE 28</span><span>         //网络设备</span></span>
<span class="line"><span>#define VIR_DEVICE 29</span><span>               //虚拟设备</span></span>
<span class="line"><span>#define FILESYS_DEVICE 30</span><span>            //文件系统设备</span></span>
<span class="line"><span>#define SYSTICK_DEVICE 31</span><span>           //系统TICK设备</span></span>
<span class="line"><span>#define UNKNOWN_DEVICE 32</span><span>        //未知设备，也是设备</span></span>
<span class="line"><span>#define HD_DEVICE 33</span><span>        //硬盘设备</span></span></code></pre></div><p>上面定义的这些类型的设备，都是Cosmos内核抽象出来的逻辑设备，例如NETWORK_DEVICE网络设备，不管它是有线网卡还是无线网卡，或者是设备控制代码虚拟出来的虚拟网卡。Cosmos内核都将认为它是一个网络设备，这就是设备的抽象，这样有利于我们灵活、简便管理设备。</p><h2 id="设备驱动" tabindex="-1">设备驱动 <a class="header-anchor" href="#设备驱动" aria-label="Permalink to &quot;设备驱动&quot;">​</a></h2><p>刚才我们解决了设备分类，下面我来研究如何实现分权而治，就是把操作每个设备的相关代码独立出来，这种方式在业界有一个更专业的名字—— <strong>设备驱动程序</strong>。同时在下面的内容中，我们将不区分设备驱动程序和驱动程序。</p><p>这种“分权而治”的方式，给操作系统内核带了灵活性、可扩展性……可是也带来了新的问题，有哪些问题呢？</p><p>首先是操作系统内核如何表示多个设备与驱动的存在？然后，还有如何组织多个设备和多个驱动程序的问题，最后我们还得考虑应该让驱动程序提供一些什么支持。下面我们分别解决这些问题。</p><h3 id="设备" tabindex="-1">设备 <a class="header-anchor" href="#设备" aria-label="Permalink to &quot;设备&quot;">​</a></h3><p>你能说说一个设备包含哪些信息吗？无非是设备类型，设备名称，设备状态，设备id，设备的驱动程序等。</p><p>我们把这些信息归纳成一个数据结构，在操作系统内核建立这个数据结构的实例变量，这个设备数据结构的实例变量，一旦建立，就表示操作系统内核中存在一个逻辑设备了。</p><p>我们接下来就一起整理一下设备的信息，然后把它们变成一个数据结构，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct s_DEVID</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint_t  dev_mtype;//设备类型号</span></span>
<span class="line"><span>    uint_t  dev_stype; //设备子类型号</span></span>
<span class="line"><span>    uint_t  dev_nr; //设备序号</span></span>
<span class="line"><span>}devid_t;</span></span>
<span class="line"><span>typedef struct s_DEVICE</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    list_h_t    dev_list;//设备链表</span></span>
<span class="line"><span>    list_h_t    dev_indrvlst; //设备在驱动程序数据结构中对应的挂载链表</span></span>
<span class="line"><span>    list_h_t    dev_intbllst; //设备在设备表数据结构中对应的挂载链表</span></span>
<span class="line"><span>    spinlock_t  dev_lock; //设备自旋锁</span></span>
<span class="line"><span>    uint_t      dev_count; //设备计数</span></span>
<span class="line"><span>    sem_t       dev_sem; //设备信号量</span></span>
<span class="line"><span>    uint_t      dev_stus; //设备状态</span></span>
<span class="line"><span>    uint_t      dev_flgs; //设备标志</span></span>
<span class="line"><span>    devid_t      dev_id; //设备ID</span></span>
<span class="line"><span>    uint_t      dev_intlnenr; //设备中断服务例程的个数</span></span>
<span class="line"><span>    list_h_t    dev_intserlst; //设备中断服务例程的链表</span></span>
<span class="line"><span>    list_h_t    dev_rqlist; //对设备的请求服务链表</span></span>
<span class="line"><span>    uint_t      dev_rqlnr; //对设备的请求服务个数</span></span>
<span class="line"><span>    sem_t       dev_waitints; //用于等待设备的信号量</span></span>
<span class="line"><span>    struct s_DRIVER* dev_drv; //设备对应的驱动程序数据结构的指针</span></span>
<span class="line"><span>    void* dev_attrb; //设备属性指针</span></span>
<span class="line"><span>    void* dev_privdata; //设备私有数据指针</span></span>
<span class="line"><span>    void* dev_userdata;//将来扩展所用</span></span>
<span class="line"><span>    void* dev_extdata;//将来扩展所用</span></span>
<span class="line"><span>    char_t* dev_name; //设备名</span></span>
<span class="line"><span>}device_t;</span></span></code></pre></div><p>设备的信息比较多，大多是用于组织设备的。这里的 <strong>设备ID结构十分重要</strong>，它表示设备的类型、设备号，子设备号是为了解决多个相同设备的，还有一个指向设备驱动程序的指针，这是用于访问设备时调用设备驱动程序的，只要有人建立了一个设备结构的实例变量，内核就能感知到一个设备存在了。</p><p>至于是谁建立了设备结构的实例变量，这个问题我们接着探索。</p><h3 id="驱动" tabindex="-1">驱动 <a class="header-anchor" href="#驱动" aria-label="Permalink to &quot;驱动&quot;">​</a></h3><p>操作系统内核和应用程序都不会主动建立设备，那么谁来建立设备呢？当然是控制设备的代码，也就是我们常说的 <strong>驱动程序</strong>。</p><p>那么驱动程序如何表示呢，换句话说，操作系统内核是如何感知到一个驱动程序的存在呢？</p><p>根据前面的经验，我们还是要定义一个数据结构来表示一个驱动程序，数据结构中应该包含驱动程序名，驱动程序ID，驱动程序所管理的设备，最重要的是 <strong>完成功能设备相关功能的函数</strong>，下面我们来定义它，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct s_DRIVER</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    spinlock_t drv_lock; //保护驱动程序数据结构的自旋锁</span></span>
<span class="line"><span>    list_h_t drv_list;//挂载驱动程序数据结构的链表</span></span>
<span class="line"><span>    uint_t drv_stuts; //驱动程序的相关状态</span></span>
<span class="line"><span>    uint_t drv_flg; //驱动程序的相关标志</span></span>
<span class="line"><span>    uint_t drv_id; //驱动程序ID</span></span>
<span class="line"><span>    uint_t drv_count; //驱动程序的计数器</span></span>
<span class="line"><span>    sem_t drv_sem; //驱动程序的信号量</span></span>
<span class="line"><span>    void* drv_safedsc; //驱动程序的安全体</span></span>
<span class="line"><span>    void* drv_attrb; //LMOSEM内核要求的驱动程序属性体</span></span>
<span class="line"><span>    void* drv_privdata; //驱动程序私有数据的指针</span></span>
<span class="line"><span>    drivcallfun_t drv_dipfun[IOIF_CODE_MAX]; //驱动程序功能派发函数指针数组</span></span>
<span class="line"><span>    list_h_t drv_alldevlist; //挂载驱动程序所管理的所有设备的链表</span></span>
<span class="line"><span>    drventyexit_t drv_entry; //驱动程序的入口函数指针</span></span>
<span class="line"><span>    drventyexit_t drv_exit; //驱动程序的退出函数指针</span></span>
<span class="line"><span>    void* drv_userdata;//用于将来扩展</span></span>
<span class="line"><span>    void* drv_extdata; //用于将来扩展</span></span>
<span class="line"><span>    char_t* drv_name; //驱动程序的名字</span></span>
<span class="line"><span>}driver_t;</span></span></code></pre></div><p>上述代码，你应该很容易看懂。Cosmos内核每加载一个驱动程序模块，就会自动分配一个驱动程序数据结构并且将其实例化。</p><p>而Cosmos内核在首次启动驱动程序时，就会调用这个驱动程序的入口点函数，在这个函数中驱动程序会分配一个设备数据结构，并用相关的信息将其实例化，比如填写正确的设备类型、设备ID号、设备名称等。</p><p>Cosmos内核负责建立驱动数据结构，而驱动程序又建立了设备数据结构，这一来二去，就形成了一个驱动程序与Cosmos内核 <strong>“握手”</strong> 的动作。</p><h3 id="设备驱动的组织" tabindex="-1">设备驱动的组织 <a class="header-anchor" href="#设备驱动的组织" aria-label="Permalink to &quot;设备驱动的组织&quot;">​</a></h3><p>有了设备、驱动，我们下面探索一下怎么合理的组织好它们。</p><p>组织它们要解决的问题，就是在哪里安放驱动。然后我们还要想好怎么找到它们，下面我们用一个叫做 <strong>设备表</strong> 的数据结构，来组织这些驱动程序数据结构和设备数据结构。</p><p>这个结构我已经帮你定义好了，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define DEVICE_MAX 34</span></span>
<span class="line"><span>typedef struct s_DEVTLST</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint_t dtl_type;//设备类型</span></span>
<span class="line"><span>    uint_t dtl_nr;//设备计数</span></span>
<span class="line"><span>    list_h_t dtl_list;//挂载设备device_t结构的链表</span></span>
<span class="line"><span>}devtlst_t;</span></span>
<span class="line"><span>typedef struct s_DEVTABLE</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    list_h_t devt_list; //设备表自身的链表</span></span>
<span class="line"><span>    spinlock_t devt_lock; //设备表自旋锁</span></span>
<span class="line"><span>    list_h_t devt_devlist; //全局设备链表</span></span>
<span class="line"><span>    list_h_t devt_drvlist; //全局驱动程序链表，驱动程序不需要分类，一个链表就行</span></span>
<span class="line"><span>    uint_t   devt_devnr; //全局设备计数</span></span>
<span class="line"><span>    uint_t   devt_drvnr; //全局驱动程序计数</span></span>
<span class="line"><span>    devtlst_t devt_devclsl[DEVICE_MAX]; //分类存放设备数据结构的devtlst_t结构数组</span></span>
<span class="line"><span>}devtable_t;</span></span></code></pre></div><p>在这段代码的devtable_t结构中，devtlst_t是每个设备类型一个，表示一类设备，但每一类可能有多个设备，所以在devtlst_t结构中，有一个设备计数和设备链表。而你可能想到Cosmos中肯定要定义一个devtable_t结构的全局变量，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//在 cosmos/kernel/krlglobal.c文件中</span></span>
<span class="line"><span>KRL_DEFGLOB_VARIABLE(devtable_t,osdevtable);</span></span>
<span class="line"><span>//在 cosmos/kernel/krldevice.c文件中</span></span>
<span class="line"><span>void devtlst_t_init(devtlst_t *initp, uint_t dtype)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    initp-&amp;gt;dtl_type = dtype;//设置设备类型    initp-&amp;gt;dtl_nr = 0;</span></span>
<span class="line"><span>    list_init(&amp;initp-&amp;gt;dtl_list);</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void devtable_t_init(devtable_t *initp)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    list_init(&amp;initp-&amp;gt;devt_list);</span></span>
<span class="line"><span>    krlspinlock_init(&amp;initp-&amp;gt;devt_lock);</span></span>
<span class="line"><span>    list_init(&amp;initp-&amp;gt;devt_devlist);</span></span>
<span class="line"><span>    list_init(&amp;initp-&amp;gt;devt_drvlist);</span></span>
<span class="line"><span>    initp-&amp;gt;devt_devnr = 0;</span></span>
<span class="line"><span>    initp-&amp;gt;devt_drvnr = 0;</span></span>
<span class="line"><span>    for (uint_t t = 0; t &amp;lt; DEVICE_MAX; t++)</span></span>
<span class="line"><span>    {//初始化设备链表</span></span>
<span class="line"><span>        devtlst_t_init(&amp;initp-&amp;gt;devt_devclsl[t], t);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void init_krldevice()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    devtable_t_init(&amp;osdevtable);//初始化系统全局设备表</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//在 cosmos/kernel/krlinit.c文件中</span></span>
<span class="line"><span>void init_krl()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    init_krlmm();</span></span>
<span class="line"><span>    init_krldevice();</span></span>
<span class="line"><span>    //记住一定要在初始化调度器之前，初始化设备表</span></span>
<span class="line"><span>    init_krlsched();</span></span>
<span class="line"><span>    init_krlcpuidle();</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的设备表的初始化代码已经写好了，如果你大脑中没有设备驱动组织图，可能脑子里还是有点乱，所以我来帮你画一幅图，如下所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/394084/17d232bd17b0c328yyed37bab98baa9f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/394084/17d232bd17b0c328yyed37bab98baa9f.jpg" alt=""></a></p><p>上图看似复杂，实则简单，我帮你理一下重点：首先devtable_t结构中能找到所有的设备和驱动，然后从设备能找到对应的驱动，从驱动也能找到其管理的所有设备 ，最后就能实现一个驱动管理多个设备。</p><h3 id="驱动程序功能" tabindex="-1">驱动程序功能 <a class="header-anchor" href="#驱动程序功能" aria-label="Permalink to &quot;驱动程序功能&quot;">​</a></h3><p>我们还有一个问题需要解决，那就是驱动程序，究竟要为操作系统内核提供哪些最基本的功能支持？</p><p>我们已经知道了，写驱动程序就是为了操控相应的设备，所以这得看大多数设备能完成什么功能了。现代计算机的设备无非就是可以输入数据、处理数据、输出数据，然后完成一些特殊的功能。</p><p>当然，现代计算机的设备很多，能耗是个严重的问题，所以操作系统内核应该能控制设备能耗。下面我来帮你归纳一下用来驱动程序的几种主要函数，如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//驱动程序入口和退出函数</span></span>
<span class="line"><span>drvstus_t device_entry(driver_t* drvp,uint_t val,void* p);</span></span>
<span class="line"><span>drvstus_t device_exit(driver_t* drvp,uint_t val,void* p);</span></span>
<span class="line"><span>//设备中断处理函数</span></span>
<span class="line"><span>drvstus_t device_handle(uint_t ift_nr,void* devp,void* sframe);</span></span>
<span class="line"><span>//打开、关闭设备函数</span></span>
<span class="line"><span>drvstus_t device_open(device_t* devp,void* iopack);</span></span>
<span class="line"><span>drvstus_t device_close(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//读、写设备数据函数</span></span>
<span class="line"><span>drvstus_t device_read(device_t* devp,void* iopack);</span></span>
<span class="line"><span>drvstus_t device_write(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//调整读写设备数据位置函数</span></span>
<span class="line"><span>drvstus_t device_lseek(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//控制设备函数</span></span>
<span class="line"><span>drvstus_t device_ioctrl(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//开启、停止设备函数</span></span>
<span class="line"><span>drvstus_t device_dev_start(device_t* devp,void* iopack);</span></span>
<span class="line"><span>drvstus_t device_dev_stop(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//设置设备电源函数</span></span>
<span class="line"><span>drvstus_t device_set_powerstus(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//枚举设备函数</span></span>
<span class="line"><span>drvstus_t device_enum_dev(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//刷新设备缓存函数</span></span>
<span class="line"><span>drvstus_t device_flush(device_t* devp,void* iopack);</span></span>
<span class="line"><span>//设备关机函数</span></span>
<span class="line"><span>drvstus_t device_shutdown(device_t* devp,void* iopack);</span></span></code></pre></div><p>如上所述，我们可以把每一个操作定义成一个函数，让驱动程序实现这些函数。函数名你可以随便写，但是函数的形式却不能改变，这是操作系统内核与驱动程序沟通的桥梁。当然有很多设备本身并不支持这么多操作，例如时钟设备，驱动程序就不必实现相应的操作。</p><p>那么这些函数如何和操作系统内核关联起来呢？还记得driver_t结构中那个函数指针数组吗，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define IOIF_CODE_OPEN 0</span><span> //对应于open操作</span></span>
<span class="line"><span>#define IOIF_CODE_CLOSE 1</span><span> //对应于close操作</span></span>
<span class="line"><span>#define IOIF_CODE_READ 2</span><span> //对应于read操作</span></span>
<span class="line"><span>#define IOIF_CODE_WRITE 3</span><span> //对应于write操作</span></span>
<span class="line"><span>#define IOIF_CODE_LSEEK 4</span><span> //对应于lseek操作</span></span>
<span class="line"><span>#define IOIF_CODE_IOCTRL 5</span><span> //对应于ioctrl操作</span></span>
<span class="line"><span>#define IOIF_CODE_DEV_START 6</span><span> //对应于start操作</span></span>
<span class="line"><span>#define IOIF_CODE_DEV_STOP 7</span><span> //对应于stop操作</span></span>
<span class="line"><span>#define IOIF_CODE_SET_POWERSTUS 8</span><span> //对应于powerstus操作</span></span>
<span class="line"><span>#define IOIF_CODE_ENUM_DEV 9</span><span> //对应于enum操作</span></span>
<span class="line"><span>#define IOIF_CODE_FLUSH 10</span><span> //对应于flush操作</span></span>
<span class="line"><span>#define IOIF_CODE_SHUTDOWN 11</span><span> //对应于shutdown操作</span></span>
<span class="line"><span>#define IOIF_CODE_MAX 12</span><span> //最大功能码</span></span>
<span class="line"><span>//驱动程序分派函数指针类型</span></span>
<span class="line"><span>typedef drvstus_t (*drivcallfun_t)(device_t*,void*);</span></span>
<span class="line"><span>//驱动程序入口、退出函数指针类型</span></span>
<span class="line"><span>typedef drvstus_t (*drventyexit_t)(struct s_DRIVER*,uint_t,void*);</span></span>
<span class="line"><span>typedef struct s_DRIVER</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    //……</span></span>
<span class="line"><span>    drivcallfun_t drv_dipfun[IOIF_CODE_MAX];//驱动程序分派函数指针数组。</span></span>
<span class="line"><span>    list_h_t drv_alldevlist;//驱动所管理的所有设备。</span></span>
<span class="line"><span>    drventyexit_t drv_entry;</span></span>
<span class="line"><span>    drventyexit_t drv_exit;</span></span>
<span class="line"><span>    //……</span></span>
<span class="line"><span>}driver_t;</span></span></code></pre></div><p>看到这里，你是不是明白了？driver_t结构中的drv_dipfun函数指针数组，正是存放上述那12个驱动程序函数的指针。这样操作系统内核就能通过driver_t结构，调用到对应的驱动程序函数操作对应的设备了。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>现在，我们搞明白了一个典型计算机的结构，里面有很多设备，需要操作系统合理地管理，而操作系统通过加载驱动程序来管理和使用设备，并为此提供了一系列的机制，这也是我们这节课的重点。</p><p>1.计算机结构，我们通过了解一个典型的计算机系统结构，明白了设备的多样性。然后我们对设备做了抽象分类，采用分权而治的方式，让操作系统通过驱动程序来管理设备，同时又能保证操作系统和驱动程序分离，达到操作系统和设备解耦的目的。</p><p>2.归纳整理设备和设备驱动的信息，抽象两个对应的数据结构，这两个数据结构在内存中的实例变量就代表一个设备和对应的驱动。然后，我们通过设备表结构组织了驱动和设备的数据结构。</p><p>3.驱动程序最主要的工作是要操控设备，但这些个操作设备的动作是操作系统调用的，所以对驱动定义了必须要支持的12种标准方法，并对应到函数，这些函数的地址保存在驱动程序的数据结构中。</p><p>你可能在想，我们驱动程序是怎么加载的，设备又是怎么建立的呢？这是正是我们后面课程要解决的。不过你可以先开动脑筋，思考一下，提出你自己的见解，考虑一下这个问题的解决方案。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你写出一个用来访问设备的接口函数，或者想一下访问一个设备需要什么参数。</p><p>欢迎你在留言区跟我交流互动，积极输出有助于更高效地理解这节课的内容。也欢迎你把这节课分享给同事、朋友。</p><p>好，我是LMOS。我们下节课见！</p>`,84)])])}const h=n(l,[["render",i]]);export{v as __pageData,h as default};
